with feeders as (
    select
        md5(upper('HUB_CLAIM|' || (HUB_CLAIM_BK__CLAIM_ID))) as HUB_CLAIM_HK
        , CASHLESS_IN_DATE as PRE_AUTH_REQUEST_DATE
        , INWARD_REMARK as AUTHORISATION_REMARKS
        , cast(null as varchar) as PRE_AUTH_AMOUNT
        , cast(null as varchar) as FINAL_AUTHORISATION_AMOUNT
        , cast(null as varchar) as PRE_AUTH_APPROVED_DATE
        , cast(null as varchar) as AUTHORISATION_MESSAGE
        , cast(null as varchar) as DENIAL_REASON
        , cast(null as varchar) as ENHANCEMENT_AMOUNT
        , cast(null as varchar) as CLAIMED_PACKAGE_AMOUNT
        , cast(null as varchar) as TPA_REFERENCE
        , cast(null as varchar) as BILL_SUBMISSION_DATE
        , 'BJAZ_HM_CASHLESS_INWARD' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_cashless_inward') }}
    where (nullif(trim(CLAIM_ID),'')) is not null
    union all
    select
        md5(upper('HUB_CLAIM|' || (HUB_CLAIM_BK__CLID))) as HUB_CLAIM_HK
        , PRE_AUTH_DATE as PRE_AUTH_REQUEST_DATE
        , AUTHORIZATION_REMARKS as AUTHORISATION_REMARKS
        , PRE_AUTH_AMT as PRE_AUTH_AMOUNT
        , AUTH_AMOUNT as FINAL_AUTHORISATION_AMOUNT
        , AUTH_DATE as PRE_AUTH_APPROVED_DATE
        , PREAUTH_EXCLAUSE as AUTHORISATION_MESSAGE
        , DENIAL_REASON as DENIAL_REASON
        , cast(null as varchar) as ENHANCEMENT_AMOUNT
        , cast(null as varchar) as CLAIMED_PACKAGE_AMOUNT
        , cast(null as varchar) as TPA_REFERENCE
        , cast(null as varchar) as BILL_SUBMISSION_DATE
        , 'BJAZ_HM_HCM_EXTRACT' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_hcm_extract') }}
    where (nullif(trim(CLID),'')) is not null
    union all
    select
        md5(upper('HUB_CLAIM|' || (HUB_CLAIM_BK__CLID))) as HUB_CLAIM_HK
        , cast(null as varchar) as PRE_AUTH_REQUEST_DATE
        , cast(null as varchar) as AUTHORISATION_REMARKS
        , cast(null as varchar) as PRE_AUTH_AMOUNT
        , TRANS_AMOUNT as FINAL_AUTHORISATION_AMOUNT
        , cast(null as varchar) as PRE_AUTH_APPROVED_DATE
        , cast(null as varchar) as AUTHORISATION_MESSAGE
        , cast(null as varchar) as DENIAL_REASON
        , ENHANCE_REQUEST as ENHANCEMENT_AMOUNT
        , cast(null as varchar) as CLAIMED_PACKAGE_AMOUNT
        , cast(null as varchar) as TPA_REFERENCE
        , cast(null as varchar) as BILL_SUBMISSION_DATE
        , 'BJAZ_HM_PREAUTH_ENHANCE' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_preauth_enhance') }}
    where (nullif(trim(CLID),'')) is not null
    union all
    select
        md5(upper('HUB_CLAIM|' || (HUB_CLAIM_BK__CLAIM_NO))) as HUB_CLAIM_HK
        , cast(null as varchar) as PRE_AUTH_REQUEST_DATE
        , PAYER_REMARKS as AUTHORISATION_REMARKS
        , cast(null as varchar) as PRE_AUTH_AMOUNT
        , cast(null as varchar) as FINAL_AUTHORISATION_AMOUNT
        , APPROVED_DATE as PRE_AUTH_APPROVED_DATE
        , cast(null as varchar) as AUTHORISATION_MESSAGE
        , cast(null as varchar) as DENIAL_REASON
        , cast(null as varchar) as ENHANCEMENT_AMOUNT
        , CLAIMED_PACKAGE_AMOUNT as CLAIMED_PACKAGE_AMOUNT
        , cast(null as varchar) as TPA_REFERENCE
        , cast(null as varchar) as BILL_SUBMISSION_DATE
        , 'BJAZ_REMEDINET_CLAIM_DETAILS' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_remedinet_claim_details') }}
    where (nullif(trim(CLAIM_NO),'')) is not null
    union all
    select
        md5(upper('HUB_CLAIM|' || (HUB_CLAIM_BK__BJAZ_CLAIM_ID))) as HUB_CLAIM_HK
        , PRE_AUTH_RECEIVED_ON as PRE_AUTH_REQUEST_DATE
        , cast(null as varchar) as AUTHORISATION_REMARKS
        , cast(null as varchar) as PRE_AUTH_AMOUNT
        , cast(null as varchar) as FINAL_AUTHORISATION_AMOUNT
        , PRE_AUTH_APPROVED_ON as PRE_AUTH_APPROVED_DATE
        , cast(null as varchar) as AUTHORISATION_MESSAGE
        , cast(null as varchar) as DENIAL_REASON
        , cast(null as varchar) as ENHANCEMENT_AMOUNT
        , cast(null as varchar) as CLAIMED_PACKAGE_AMOUNT
        , TPA_CLAIM_NO as TPA_REFERENCE
        , DATE_OF_DOC_REC as BILL_SUBMISSION_DATE
        , 'BJAZ_TPA_CLAIM_DETAILS_WS' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_tpa_claim_details_ws') }}
    where (nullif(trim(BJAZ_CLAIM_ID),'')) is not null
    union all
    select
        md5(upper('HUB_CLAIM|' || (HUB_CLAIM_BK__CLAIM_ID))) as HUB_CLAIM_HK
        , INSERTED_DATE as PRE_AUTH_REQUEST_DATE
        , cast(null as varchar) as AUTHORISATION_REMARKS
        , PREAUT_AMT as PRE_AUTH_AMOUNT
        , cast(null as varchar) as FINAL_AUTHORISATION_AMOUNT
        , cast(null as varchar) as PRE_AUTH_APPROVED_DATE
        , cast(null as varchar) as AUTHORISATION_MESSAGE
        , cast(null as varchar) as DENIAL_REASON
        , cast(null as varchar) as ENHANCEMENT_AMOUNT
        , cast(null as varchar) as CLAIMED_PACKAGE_AMOUNT
        , cast(null as varchar) as TPA_REFERENCE
        , cast(null as varchar) as BILL_SUBMISSION_DATE
        , 'BJAZ_HM_PREAUTH_REQUEST' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_preauth_request') }}
    where (nullif(trim(CLAIM_ID),'')) is not null
),

resolved as (
    select
        HUB_CLAIM_HK,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then PRE_AUTH_REQUEST_DATE end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then PRE_AUTH_REQUEST_DATE end)) as PRE_AUTH_REQUEST_DATE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then AUTHORISATION_REMARKS end) as AUTHORISATION_REMARKS,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then PRE_AUTH_AMOUNT end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then PRE_AUTH_AMOUNT end)) as PRE_AUTH_AMOUNT,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then FINAL_AUTHORISATION_AMOUNT end) as FINAL_AUTHORISATION_AMOUNT,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then PRE_AUTH_APPROVED_DATE end) as PRE_AUTH_APPROVED_DATE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then AUTHORISATION_MESSAGE end) as AUTHORISATION_MESSAGE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then DENIAL_REASON end) as DENIAL_REASON,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then ENHANCEMENT_AMOUNT end) as ENHANCEMENT_AMOUNT,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then CLAIMED_PACKAGE_AMOUNT end) as CLAIMED_PACKAGE_AMOUNT,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then TPA_REFERENCE end) as TPA_REFERENCE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then BILL_SUBMISSION_DATE end) as BILL_SUBMISSION_DATE,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_CLAIM_HK
),

hashed as (
    select
        *,
        case when PRE_AUTH_REQUEST_DATE is not null or AUTHORISATION_REMARKS is not null or PRE_AUTH_AMOUNT is not null or FINAL_AUTHORISATION_AMOUNT is not null or PRE_AUTH_APPROVED_DATE is not null or AUTHORISATION_MESSAGE is not null or DENIAL_REASON is not null or ENHANCEMENT_AMOUNT is not null or CLAIMED_PACKAGE_AMOUNT is not null or TPA_REFERENCE is not null or BILL_SUBMISSION_DATE is not null
                     then md5(upper(coalesce(cast(PRE_AUTH_REQUEST_DATE as varchar), '') || '|' || coalesce(cast(AUTHORISATION_REMARKS as varchar), '') || '|' || coalesce(cast(PRE_AUTH_AMOUNT as varchar), '') || '|' || coalesce(cast(FINAL_AUTHORISATION_AMOUNT as varchar), '') || '|' || coalesce(cast(PRE_AUTH_APPROVED_DATE as varchar), '') || '|' || coalesce(cast(AUTHORISATION_MESSAGE as varchar), '') || '|' || coalesce(cast(DENIAL_REASON as varchar), '') || '|' || coalesce(cast(ENHANCEMENT_AMOUNT as varchar), '') || '|' || coalesce(cast(CLAIMED_PACKAGE_AMOUNT as varchar), '') || '|' || coalesce(cast(TPA_REFERENCE as varchar), '') || '|' || coalesce(cast(BILL_SUBMISSION_DATE as varchar), '')))
                end as SAT_CLAIM_TPA_INTERACTION_HASHDIFF
    from resolved
)

select * from hashed
where HUB_CLAIM_HK is not null
  and SAT_CLAIM_TPA_INTERACTION_HASHDIFF is not null
